python3 -c "
import zipfile
import xml.etree.ElementTree as ET

ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

cats = {}
total = 0.0
for row in root.findall('.//m:row', ns):
    r = int(row.get('r'))
    if 11 <= r <= 22:
        cells = {c.get('r'): c for c in row.findall('m:c', ns)}
        cat = cells.get(f'A{r}').find('m:is/m:t', ns).text
        val = float(cells.get(f'C{r}').find('m:v', ns).text)
        cats.setdefault(cat, []).append((cells.get(f'B{r}').find('m:is/m:t', ns).text, val))
        total += val

for cat, items in cats.items():
    print(f'{cat}: ' + ' + '.join(f'{n} ({v:g})' for n, v in items) + f' = {sum(v for _, v in items):g}')
print('TOTAL EXPENSES (C11:C22) =', f'{total:g}')
"
